#!/usr/bin/env python3
"""Super dummy UCI engine that always says Black is winning"""
import sys, time, re

def send(msg):
    sys.stdout.write(msg + "\n")
    sys.stdout.flush()

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.strip()
        if line == "uci":
            send("id name DummyEngine")
            send("id author OpenAI")
            send("uciok")
        elif line == "isready":
            send("readyok")
        elif line == "ucinewgame":
            # nothing to reset
            pass
        elif line.startswith("quit"):
            break
        elif line.startswith("go"):
            # Always evaluate as large advantage to Black and choose null move
            send("info depth 1 score cp -10000")
            send("bestmove 0000")
        else:
            # ignore other commands like position, setoption, stop, ponderhit, etc.
            pass

if __name__ == "__main__":
    main()
